begin;
alter table public.ashyk_rooms add column if not exists protocol_version integer;
update public.ashyk_rooms set protocol_version=1 where protocol_version is null;
alter table public.ashyk_rooms alter column protocol_version set default 2;
alter table public.ashyk_rooms alter column protocol_version set not null;
alter table public.ashyk_rooms add column if not exists turn_no bigint not null default 0,add column if not exists phase text not null default 'first-shot',add column if not exists phase_seq bigint not null default 0,add column if not exists phase_started_at timestamptz,add column if not exists phase_deadline_at timestamptz,add column if not exists last_action_id text,add column if not exists last_action_type text,add column if not exists last_action_actor_user_id uuid references auth.users(id) on delete set null,add column if not exists winner_user_id uuid references auth.users(id) on delete set null,add column if not exists finish_reason text;
alter table public.ashyk_rooms drop constraint if exists ashyk_rooms_phase_check;
alter table public.ashyk_rooms add constraint ashyk_rooms_phase_check check(phase in ('first-shot','bonus-question','bonus-shot'));
create table if not exists public.ashyk_action_log(id bigint generated by default as identity primary key,room_id uuid not null references public.ashyk_rooms(id) on delete cascade,revision_after bigint not null,phase_seq_after bigint not null,actor_user_id uuid references auth.users(id) on delete set null,action_id text not null,action_type text not null,created_at timestamptz not null default now(),unique(room_id,action_id));
alter table public.ashyk_action_log enable row level security;
revoke all on public.ashyk_action_log from anon,authenticated;
grant select on public.ashyk_action_log to authenticated;
drop policy if exists ashyk_action_log_members_read on public.ashyk_action_log;
create policy ashyk_action_log_members_read on public.ashyk_action_log for select to authenticated using(exists(select 1 from public.ashyk_rooms r where r.id=room_id and (auth.uid()=r.host_user_id or auth.uid()=r.guest_user_id)));
create or replace function private.ashyk_phase_seconds(p_state jsonb,p_phase text) returns integer language sql immutable set search_path='' as $$select case when p_phase='bonus-question' then case coalesce(p_state->>'difficulty','normal') when 'easy' then 15 when 'hard' then 7 else 10 end else case coalesce(p_state->>'difficulty','normal') when 'easy' then 20 else 15 end end$$;
create or replace function private.ashyk_clean_state(p_state jsonb,p_phase text,p_player integer) returns jsonb language sql immutable set search_path='' as $$select (coalesce(p_state,'{}'::jsonb)-'shotSeconds'-'questionSeconds')||jsonb_build_object('phase',p_phase,'currentPlayer',p_player)||case when p_phase='first-shot' then jsonb_build_object('question',null,'questionLocked',false,'wrongAnswerId',null) when p_phase='bonus-shot' then jsonb_build_object('question',null,'questionLocked',true,'wrongAnswerId',null) else '{}'::jsonb end$$;
create or replace function private.ashyk_resolve_timeout_locked(p_room_id uuid) returns public.ashyk_rooms language plpgsql security definer set search_path='' as $$
declare v_room public.ashyk_rooms;v_next uuid;v_next_player integer;v_action_id text;v_state jsonb;
begin
select * into v_room from public.ashyk_rooms where id=p_room_id for update;
if v_room.id is null or v_room.status<>'playing' or v_room.phase_deadline_at is null or v_room.phase_deadline_at>now() then return v_room; end if;
v_next:=case when v_room.active_user_id=v_room.host_user_id then v_room.guest_user_id else v_room.host_user_id end;if v_next is null then return v_room; end if;
v_next_player:=case when v_next=v_room.host_user_id then 1 else 2 end;v_action_id:='server-timeout:'||v_room.phase_seq::text;v_state:=private.ashyk_clean_state(v_room.game_state,'first-shot',v_next_player);
update public.ashyk_rooms set game_state=v_state,active_user_id=v_next,revision=revision+1,turn_no=turn_no+1,phase='first-shot',phase_seq=phase_seq+1,phase_started_at=now(),phase_deadline_at=now()+make_interval(secs=>private.ashyk_phase_seconds(v_state,'first-shot')),last_action_id=v_action_id,last_action_type='timeout',last_action_actor_user_id=null,updated_at=now() where id=p_room_id returning * into v_room;
insert into public.ashyk_action_log(room_id,revision_after,phase_seq_after,actor_user_id,action_id,action_type) values(v_room.id,v_room.revision,v_room.phase_seq,null,v_action_id,'timeout') on conflict(room_id,action_id) do nothing;return v_room;
end $$;
create or replace function public.ashyk_resolve_timeout(p_room_id uuid) returns public.ashyk_rooms language plpgsql security definer set search_path='' as $$
declare v_actor uuid:=auth.uid();v_room public.ashyk_rooms;begin if v_actor is null then raise exception 'authentication required' using errcode='42501';end if;select * into v_room from public.ashyk_rooms where id=p_room_id;if v_room.id is null then raise exception 'room not found' using errcode='P0002';end if;if v_actor<>v_room.host_user_id and v_actor is distinct from v_room.guest_user_id then raise exception 'not a room member' using errcode='42501';end if;return private.ashyk_resolve_timeout_locked(p_room_id);end $$;
create or replace function public.ashyk_room_get(p_room_id uuid) returns public.ashyk_rooms language plpgsql security definer set search_path='' as $$
declare v_actor uuid:=auth.uid();v_room public.ashyk_rooms;begin if v_actor is null then raise exception 'authentication required' using errcode='42501';end if;perform private.expire_ashyk_sessions();select * into v_room from public.ashyk_rooms where id=p_room_id;if v_room.id is null then raise exception 'room not found' using errcode='P0002';end if;if v_actor<>v_room.host_user_id and v_actor is distinct from v_room.guest_user_id then raise exception 'not a room member' using errcode='42501';end if;if v_room.status='playing' then v_room:=private.ashyk_resolve_timeout_locked(p_room_id);end if;return v_room;end $$;
create or replace function public.ashyk_active_room() returns setof public.ashyk_rooms language plpgsql security definer set search_path='' as $$
declare v_actor uuid:=auth.uid();v_room public.ashyk_rooms;begin if v_actor is null then raise exception 'authentication required' using errcode='42501';end if;perform private.expire_ashyk_sessions();select * into v_room from public.ashyk_rooms r where (r.host_user_id=v_actor or r.guest_user_id=v_actor) and r.status in ('waiting','preparing','playing') order by r.updated_at desc limit 1;if v_room.id is null then return;end if;if v_room.status='playing' then v_room:=private.ashyk_resolve_timeout_locked(v_room.id);end if;if v_room.status in ('waiting','preparing','playing') then return next v_room;end if;end $$;
create or replace function public.ashyk_room_ping(p_room_id uuid) returns public.ashyk_rooms language plpgsql security definer set search_path='' as $$
declare v_actor uuid:=auth.uid();v_room public.ashyk_rooms;begin if v_actor is null then raise exception 'authentication required' using errcode='42501';end if;perform private.expire_ashyk_sessions();select * into v_room from public.ashyk_rooms where id=p_room_id;if v_room.id is null then raise exception 'room not found' using errcode='P0002';end if;if v_actor<>v_room.host_user_id and v_actor is distinct from v_room.guest_user_id then raise exception 'not a room member' using errcode='42501';end if;if v_room.status='playing' then v_room:=private.ashyk_resolve_timeout_locked(p_room_id);end if;if v_room.status not in ('waiting','preparing','playing') then return v_room;end if;update public.ashyk_rooms set host_seen_at=case when v_actor=host_user_id then now() else host_seen_at end,guest_seen_at=case when v_actor=guest_user_id then now() else guest_seen_at end where id=p_room_id returning * into v_room;return v_room;end $$;
create or replace function public.ashyk_room_ready(p_room_id uuid) returns public.ashyk_rooms language plpgsql security definer set search_path='' as $$
declare v_actor uuid:=auth.uid();v_room public.ashyk_rooms;v_state jsonb;begin if v_actor is null then raise exception 'authentication required' using errcode='42501';end if;perform private.expire_ashyk_sessions();select * into v_room from public.ashyk_rooms where id=p_room_id for update;if v_room.id is null then raise exception 'room not found' using errcode='P0002';end if;if v_actor<>v_room.host_user_id and v_actor is distinct from v_room.guest_user_id then raise exception 'not a room member' using errcode='42501';end if;if v_room.status not in ('waiting','preparing','playing') then return v_room;end if;update public.ashyk_rooms set host_ready_at=case when v_actor=host_user_id then coalesce(host_ready_at,now()) else host_ready_at end,guest_ready_at=case when v_actor=guest_user_id then coalesce(guest_ready_at,now()) else guest_ready_at end,host_seen_at=case when v_actor=host_user_id then now() else host_seen_at end,guest_seen_at=case when v_actor=guest_user_id then now() else guest_seen_at end where id=p_room_id returning * into v_room;
if v_room.guest_user_id is not null and v_room.host_ready_at is not null and v_room.guest_ready_at is not null and v_room.host_seen_at>=now()-interval '30 seconds' and v_room.guest_seen_at>=now()-interval '30 seconds' and v_room.status<>'playing' then v_state:=private.ashyk_clean_state(v_room.game_state,'first-shot',1);update public.ashyk_rooms set protocol_version=2,status='playing',active_user_id=host_user_id,game_state=v_state,started_at=coalesce(started_at,now()),turn_no=1,phase='first-shot',phase_seq=greatest(phase_seq,0)+1,phase_started_at=now(),phase_deadline_at=now()+make_interval(secs=>private.ashyk_phase_seconds(v_state,'first-shot')),last_action_id='server-start:'||(greatest(phase_seq,0)+1)::text,last_action_type='start',last_action_actor_user_id=null,revision=revision+1,updated_at=now() where id=p_room_id returning * into v_room;insert into public.ashyk_action_log(room_id,revision_after,phase_seq_after,actor_user_id,action_id,action_type) values(v_room.id,v_room.revision,v_room.phase_seq,null,v_room.last_action_id,'start') on conflict(room_id,action_id) do nothing;end if;return v_room;end $$;
create or replace function public.ashyk_invite_create(p_friend_user_id uuid,p_initial_state jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_actor uuid:=auth.uid();v_room public.ashyk_rooms;v_invite public.ashyk_invites;v_state jsonb;begin if v_actor is null then raise exception 'authentication required' using errcode='42501';end if;perform private.expire_ashyk_sessions();if p_friend_user_id is null or p_friend_user_id=v_actor then raise exception 'invalid friend';end if;if not private.social_are_friends(v_actor,p_friend_user_id) or private.social_blocked(v_actor,p_friend_user_id) then raise exception 'friend unavailable' using errcode='42501';end if;perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('ashyk-user:'||least(v_actor::text,p_friend_user_id::text),0));perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('ashyk-user:'||greatest(v_actor::text,p_friend_user_id::text),0));select * into v_invite from public.ashyk_invites i where i.status='pending' and ((i.host_user_id=v_actor and i.friend_user_id=p_friend_user_id) or (i.host_user_id=p_friend_user_id and i.friend_user_id=v_actor)) order by i.created_at desc limit 1;if v_invite.id is not null then if v_invite.host_user_id<>v_actor then raise exception 'invite already pending' using errcode='P0001';end if;select * into v_room from public.ashyk_rooms where id=v_invite.room_id;return jsonb_build_object('invite',to_jsonb(v_invite),'room',to_jsonb(v_room));end if;if exists(select 1 from public.ashyk_rooms r where (r.host_user_id=v_actor or r.guest_user_id=v_actor) and r.status in ('waiting','preparing','playing')) then raise exception 'active game exists' using errcode='P0001';end if;if exists(select 1 from public.ashyk_rooms r where (r.host_user_id=p_friend_user_id or r.guest_user_id=p_friend_user_id) and r.status in ('waiting','preparing','playing')) then raise exception 'friend already playing' using errcode='P0001';end if;v_state:=private.ashyk_clean_state(coalesce(p_initial_state,'{}'::jsonb),'first-shot',1);insert into public.ashyk_rooms(protocol_version,status,host_user_id,active_user_id,game_state,turn_no,phase,phase_seq,host_seen_at) values(2,'waiting',v_actor,v_actor,v_state,0,'first-shot',0,now()) returning * into v_room;insert into public.ashyk_invites(room_id,host_user_id,friend_user_id) values(v_room.id,v_actor,p_friend_user_id) returning * into v_invite;return jsonb_build_object('invite',to_jsonb(v_invite),'room',to_jsonb(v_room));end $$;
create or replace function public.ashyk_submit_action(p_room_id uuid,p_expected_revision bigint,p_expected_phase_seq bigint,p_action_id text,p_action_type text,p_state jsonb,p_next_active_user_id uuid,p_status text default 'playing') returns public.ashyk_rooms language plpgsql security definer set search_path='' as $$
declare v_actor uuid:=auth.uid();v_room public.ashyk_rooms;v_other uuid;v_actor_index integer;v_other_index integer;v_actor_player integer;v_next_player integer;v_old_scores jsonb;v_new_scores jsonb;v_old_actor_score integer;v_new_actor_score integer;v_old_other_score integer;v_new_other_score integer;v_delta integer;v_old_remaining integer;v_new_remaining integer;v_next_phase text;v_clean_state jsonb;v_winner_player integer;v_winner_user uuid;v_turn_no bigint;
begin
if v_actor is null then raise exception 'authentication required' using errcode='42501';end if;if coalesce(trim(p_action_id),'')='' then raise exception 'missing action id';end if;if p_action_type not in ('shot_result','answer_correct','answer_wrong','skip') then raise exception 'invalid action type';end if;if p_status not in ('playing','finished') then raise exception 'invalid room status';end if;select * into v_room from public.ashyk_rooms where id=p_room_id for update;if v_room.id is null then raise exception 'room not found' using errcode='P0002';end if;if v_actor<>v_room.host_user_id and v_actor is distinct from v_room.guest_user_id then raise exception 'not a room member' using errcode='42501';end if;if exists(select 1 from public.ashyk_action_log l where l.room_id=p_room_id and l.action_id=p_action_id) then return v_room;end if;if v_room.status<>'playing' then raise exception 'room is not playing' using errcode='P0001';end if;if v_actor<>v_room.active_user_id then raise exception 'not your turn' using errcode='42501';end if;if v_room.revision<>p_expected_revision then raise exception 'stale room revision' using errcode='40001';end if;if v_room.phase_seq<>p_expected_phase_seq then raise exception 'stale room phase' using errcode='40001';end if;if v_room.phase_deadline_at is not null and v_room.phase_deadline_at<=now() then return private.ashyk_resolve_timeout_locked(p_room_id);end if;
v_other:=case when v_actor=v_room.host_user_id then v_room.guest_user_id else v_room.host_user_id end;if v_other is null then raise exception 'opponent missing' using errcode='P0001';end if;if p_next_active_user_id<>v_room.host_user_id and p_next_active_user_id is distinct from v_room.guest_user_id then raise exception 'invalid next player';end if;v_actor_index:=case when v_actor=v_room.host_user_id then 0 else 1 end;v_other_index:=case when v_actor_index=0 then 1 else 0 end;v_actor_player:=v_actor_index+1;v_next_player:=case when p_next_active_user_id=v_room.host_user_id then 1 else 2 end;v_old_scores:=coalesce(v_room.game_state->'scores','[0,0]'::jsonb);v_new_scores:=coalesce(p_state->'scores',v_old_scores);if jsonb_typeof(v_old_scores)<>'array' or jsonb_typeof(v_new_scores)<>'array' or jsonb_array_length(v_old_scores)<2 or jsonb_array_length(v_new_scores)<2 then raise exception 'invalid scores';end if;v_old_actor_score:=coalesce((v_old_scores->>v_actor_index)::integer,0);v_new_actor_score:=coalesce((v_new_scores->>v_actor_index)::integer,0);v_old_other_score:=coalesce((v_old_scores->>v_other_index)::integer,0);v_new_other_score:=coalesce((v_new_scores->>v_other_index)::integer,0);if v_old_other_score<>v_new_other_score then raise exception 'opponent score mutation rejected';end if;v_delta:=v_new_actor_score-v_old_actor_score;v_old_remaining:=coalesce((v_room.game_state->>'remainingAshyks')::integer,10);v_new_remaining:=coalesce((p_state->>'remainingAshyks')::integer,v_old_remaining);if v_new_remaining<1 or v_new_remaining>v_old_remaining or v_old_remaining-v_new_remaining>1 then raise exception 'invalid remaining pieces';end if;v_next_phase:=coalesce(p_state->>'phase','first-shot');if v_next_phase not in ('first-shot','bonus-question','bonus-shot') then raise exception 'invalid next phase';end if;
if p_action_type='shot_result' then if v_room.phase not in ('first-shot','bonus-shot') then raise exception 'shot not allowed in this phase';end if;if v_delta not in (-1,0,1,2,3,4,6,15) then raise exception 'invalid shot score delta';end if;if v_delta>0 and v_old_remaining-v_new_remaining<>1 then raise exception 'capture must remove one piece';end if;if v_delta<0 and v_old_remaining<>v_new_remaining then raise exception 'miss cannot remove a piece';end if;if p_status='finished' then if not (coalesce((p_state->>'winByKyt')::boolean,false) or v_new_remaining<=1) then raise exception 'invalid finish';end if;if p_next_active_user_id<>v_actor then raise exception 'finished action must remain with actor';end if;elsif v_next_phase='bonus-question' then if p_next_active_user_id<>v_actor or v_delta<=0 or v_old_remaining-v_new_remaining<>1 or p_state->'question' is null then raise exception 'invalid bonus question transition';end if;elsif v_next_phase='first-shot' then if p_next_active_user_id<>v_other then raise exception 'shot must pass turn';end if;else raise exception 'invalid shot transition';end if;
elsif p_action_type='answer_correct' then if v_room.phase<>'bonus-question' or p_status<>'playing' or v_next_phase<>'bonus-shot' or p_next_active_user_id<>v_actor or v_delta<>3 or v_new_remaining<>v_old_remaining then raise exception 'invalid correct-answer transition';end if;
elsif p_action_type='answer_wrong' then if v_room.phase<>'bonus-question' or p_status<>'playing' or v_next_phase<>'first-shot' or p_next_active_user_id<>v_other or v_delta<>-1 or v_new_remaining<>v_old_remaining then raise exception 'invalid wrong-answer transition';end if;
elsif p_action_type='skip' then if v_room.phase<>'bonus-question' or p_status<>'playing' or v_next_phase<>'first-shot' or p_next_active_user_id<>v_other or v_delta<>0 or v_new_remaining<>v_old_remaining then raise exception 'invalid skip transition';end if;end if;
v_clean_state:=private.ashyk_clean_state(p_state,v_next_phase,v_next_player);v_turn_no:=v_room.turn_no+case when p_status='playing' and p_next_active_user_id<>v_actor then 1 else 0 end;v_winner_user:=null;
if p_status='finished' then if coalesce((p_state->>'winByKyt')::boolean,false) then v_winner_player:=v_actor_player;v_winner_user:=v_actor;elsif coalesce((v_new_scores->>0)::integer,0)=coalesce((v_new_scores->>1)::integer,0) then v_winner_player:=null;v_clean_state:=v_clean_state||jsonb_build_object('winner','draw');elsif coalesce((v_new_scores->>0)::integer,0)>coalesce((v_new_scores->>1)::integer,0) then v_winner_player:=1;v_winner_user:=v_room.host_user_id;else v_winner_player:=2;v_winner_user:=v_room.guest_user_id;end if;if v_winner_player is not null then v_clean_state:=v_clean_state||jsonb_build_object('winner',v_winner_player);end if;end if;
update public.ashyk_rooms set game_state=v_clean_state,active_user_id=p_next_active_user_id,status=p_status,revision=revision+1,turn_no=v_turn_no,phase=v_next_phase,phase_seq=phase_seq+1,phase_started_at=case when p_status='playing' then now() else phase_started_at end,phase_deadline_at=case when p_status='playing' then now()+make_interval(secs=>private.ashyk_phase_seconds(v_clean_state,v_next_phase)) else null end,last_action_id=p_action_id,last_action_type=p_action_type,last_action_actor_user_id=v_actor,winner_user_id=case when p_status='finished' then v_winner_user else winner_user_id end,finish_reason=case when p_status='finished' then case when coalesce((p_state->>'winByKyt')::boolean,false) then 'kyt' else 'score' end else finish_reason end,host_seen_at=case when v_actor=host_user_id then now() else host_seen_at end,guest_seen_at=case when v_actor=guest_user_id then now() else guest_seen_at end,ended_at=case when p_status='finished' then coalesce(ended_at,now()) else ended_at end,updated_at=now() where id=p_room_id returning * into v_room;
insert into public.ashyk_action_log(room_id,revision_after,phase_seq_after,actor_user_id,action_id,action_type) values(v_room.id,v_room.revision,v_room.phase_seq,v_actor,p_action_id,p_action_type) on conflict(room_id,action_id) do nothing;return v_room;end $$;
create or replace function public.ashyk_submit_state(p_room_id uuid,p_expected_revision bigint,p_state jsonb,p_next_active_user_id uuid,p_status text default 'playing') returns public.ashyk_rooms language plpgsql security definer set search_path='' as $$
declare v_actor uuid:=auth.uid();v_room public.ashyk_rooms;v_phase text;v_player integer;v_state jsonb;begin if v_actor is null then raise exception 'authentication required' using errcode='42501';end if;if p_status not in ('playing','finished') then raise exception 'invalid room status';end if;select * into v_room from public.ashyk_rooms where id=p_room_id for update;if v_room.id is null then raise exception 'room not found' using errcode='P0002';end if;if v_actor<>v_room.host_user_id and v_actor is distinct from v_room.guest_user_id then raise exception 'not a room member' using errcode='42501';end if;if v_room.status<>'playing' then raise exception 'room is not playing' using errcode='P0001';end if;if v_actor<>v_room.active_user_id then raise exception 'not your turn' using errcode='42501';end if;if v_room.revision<>p_expected_revision then raise exception 'stale room revision' using errcode='40001';end if;if v_room.phase_deadline_at is not null and v_room.phase_deadline_at<=now() then return private.ashyk_resolve_timeout_locked(p_room_id);end if;if p_next_active_user_id<>v_room.host_user_id and p_next_active_user_id is distinct from v_room.guest_user_id then raise exception 'invalid next player';end if;v_phase:=case when p_status='finished' then coalesce(p_state->>'phase',v_room.phase) else coalesce(p_state->>'phase','first-shot') end;if v_phase not in ('first-shot','bonus-question','bonus-shot') then v_phase:='first-shot';end if;v_player:=case when p_next_active_user_id=v_room.host_user_id then 1 else 2 end;v_state:=private.ashyk_clean_state(p_state,v_phase,v_player);update public.ashyk_rooms set game_state=v_state,active_user_id=p_next_active_user_id,status=p_status,revision=revision+1,turn_no=turn_no+case when p_status='playing' and p_next_active_user_id<>v_actor then 1 else 0 end,phase=v_phase,phase_seq=phase_seq+1,phase_started_at=case when p_status='playing' then now() else phase_started_at end,phase_deadline_at=case when p_status='playing' then now()+make_interval(secs=>private.ashyk_phase_seconds(v_state,v_phase)) else null end,last_action_id='legacy:'||(revision+1)::text,last_action_type='legacy_state',last_action_actor_user_id=v_actor,host_seen_at=case when v_actor=host_user_id then now() else host_seen_at end,guest_seen_at=case when v_actor=guest_user_id then now() else guest_seen_at end,ended_at=case when p_status='finished' then coalesce(ended_at,now()) else ended_at end,updated_at=now() where id=p_room_id returning * into v_room;insert into public.ashyk_action_log(room_id,revision_after,phase_seq_after,actor_user_id,action_id,action_type) values(v_room.id,v_room.revision,v_room.phase_seq,v_actor,v_room.last_action_id,'legacy_state') on conflict(room_id,action_id) do nothing;return v_room;end $$;
create or replace function public.ashyk_leave_room(p_room_id uuid) returns void language plpgsql security definer set search_path='' as $$
declare v_actor uuid:=auth.uid();v_room public.ashyk_rooms;v_winner uuid;v_winner_player integer;v_state jsonb;v_action text;begin if v_actor is null then raise exception 'authentication required' using errcode='42501';end if;select * into v_room from public.ashyk_rooms where id=p_room_id for update;if v_room.id is null then return;end if;if v_actor<>v_room.host_user_id and v_actor is distinct from v_room.guest_user_id then raise exception 'not a room member' using errcode='42501';end if;if v_room.status='playing' and v_room.guest_user_id is not null then v_winner:=case when v_actor=v_room.host_user_id then v_room.guest_user_id else v_room.host_user_id end;v_winner_player:=case when v_winner=v_room.host_user_id then 1 else 2 end;v_state:=(v_room.game_state-'shotSeconds'-'questionSeconds')||jsonb_build_object('winner',v_winner_player,'phase',v_room.phase);v_action:='server-resign:'||(v_room.revision+1)::text;update public.ashyk_rooms set status='finished',game_state=v_state,winner_user_id=v_winner,finish_reason='resign',revision=revision+1,phase_seq=phase_seq+1,phase_deadline_at=null,last_action_id=v_action,last_action_type='resign',last_action_actor_user_id=v_actor,ended_at=coalesce(ended_at,now()),updated_at=now() where id=p_room_id returning * into v_room;insert into public.ashyk_action_log(room_id,revision_after,phase_seq_after,actor_user_id,action_id,action_type) values(v_room.id,v_room.revision,v_room.phase_seq,v_actor,v_action,'resign') on conflict(room_id,action_id) do nothing;elsif v_room.status in ('waiting','preparing') then update public.ashyk_rooms set status='abandoned',revision=revision+1,ended_at=coalesce(ended_at,now()),updated_at=now() where id=p_room_id;end if;update public.ashyk_invites set status='cancelled',updated_at=now() where room_id=p_room_id and status='pending';end $$;
create or replace function public.ashyk_claim_forfeit(p_room_id uuid) returns public.ashyk_rooms language plpgsql security definer set search_path='' as $$
declare v_actor uuid:=auth.uid();v_room public.ashyk_rooms;v_opponent_seen timestamptz;v_winner_player integer;v_state jsonb;v_action text;begin if v_actor is null then raise exception 'authentication required' using errcode='42501';end if;select * into v_room from public.ashyk_rooms where id=p_room_id for update;if v_room.id is null then raise exception 'room not found' using errcode='P0002';end if;if v_actor<>v_room.host_user_id and v_actor is distinct from v_room.guest_user_id then raise exception 'not a room member' using errcode='42501';end if;if v_room.status<>'playing' then return v_room;end if;v_opponent_seen:=case when v_actor=v_room.host_user_id then coalesce(v_room.guest_seen_at,v_room.started_at,v_room.updated_at) else coalesce(v_room.host_seen_at,v_room.started_at,v_room.updated_at) end;if v_opponent_seen>now()-interval '120 seconds' then raise exception 'opponent is still connected' using errcode='P0001';end if;v_winner_player:=case when v_actor=v_room.host_user_id then 1 else 2 end;v_state:=(v_room.game_state-'shotSeconds'-'questionSeconds')||jsonb_build_object('winner',v_winner_player,'phase',v_room.phase);v_action:='server-forfeit:'||(v_room.revision+1)::text;update public.ashyk_rooms set status='finished',game_state=v_state,winner_user_id=v_actor,finish_reason='disconnect',revision=revision+1,phase_seq=phase_seq+1,phase_deadline_at=null,last_action_id=v_action,last_action_type='forfeit',last_action_actor_user_id=v_actor,ended_at=coalesce(ended_at,now()),updated_at=now() where id=p_room_id returning * into v_room;insert into public.ashyk_action_log(room_id,revision_after,phase_seq_after,actor_user_id,action_id,action_type) values(v_room.id,v_room.revision,v_room.phase_seq,v_actor,v_action,'forfeit') on conflict(room_id,action_id) do nothing;return v_room;end $$;
update public.ashyk_rooms set status='abandoned',ended_at=coalesce(ended_at,now()),revision=revision+1,finish_reason='protocol_upgrade',updated_at=now() where status in ('waiting','preparing','playing') and protocol_version<2;
revoke all on function public.ashyk_submit_action(uuid,bigint,bigint,text,text,jsonb,uuid,text) from public,anon;
revoke all on function public.ashyk_resolve_timeout(uuid) from public,anon;
revoke all on function public.ashyk_claim_forfeit(uuid) from public,anon;
grant execute on function public.ashyk_submit_action(uuid,bigint,bigint,text,text,jsonb,uuid,text) to authenticated;
grant execute on function public.ashyk_resolve_timeout(uuid) to authenticated;
grant execute on function public.ashyk_claim_forfeit(uuid) to authenticated;
commit;
